import csv
import json
from decimal import Decimal
import datetime

def parse_date(val):
    if val is None:
        return None
    val = val.strip()
    if not val:
        return None

    # Check if value is an Excel serial date number
    try:
        num = float(val)
        dt = datetime.date(1899, 12, 30) + datetime.timedelta(days=int(round(num)))
        return dt.strftime("%Y-%m-%d")
    except ValueError:
        pass

    # Try parsing common calendar date formats
    for fmt in ("%Y-%m-%d", "%m/%d/%Y", "%d/%m/%Y", "%Y/%m/%d", "%m-%d-%Y", "%B %d, %Y", "%b %d, %Y"):
        try:
            dt = datetime.datetime.strptime(val, fmt).date()
            return dt.strftime("%Y-%m-%d")
        except ValueError:
            pass

    return val

def format_amount(val):
    if val is None:
        return None
    val = val.strip()
    if not val:
        return None
    val = val.replace("$", "").replace(",", "")
    try:
        d = Decimal(val)
        if d == d.to_integral():
            return str(int(d))
        else:
            s = f"{d:f}"
            return s.rstrip('0').rstrip('.') if '.' in s else s
    except Exception:
        return val

FACT_CONFIG = {
    "offered wage": ("WAGE_RATE_OF_PAY_FROM", format_amount, "lca_disclosure"),
    "prevailing wage": ("PREVAILING_WAGE", format_amount, "lca_disclosure"),
    "begin date": ("BEGIN_DATE", parse_date, "lca_disclosure"),
    "end date": ("END_DATE", parse_date, "lca_disclosure"),
}

def main():
    if len(sys.argv) < 3:
        sys.exit(1)

    packet_dir = sys.argv[1]
    manifest_path = sys.argv[2]

    with open(manifest_path, "r", encoding="utf-8") as f:
        manifest = json.load(f)

    lca_file_path = os.path.join(packet_dir, "lca_disclosure.csv")
    entity_records = {}

    if os.path.exists(lca_file_path):
        with open(lca_file_path, "r", encoding="utf-8-sig") as f:
            reader = csv.DictReader(f)
            for row in reader:
                cleaned_row = {
                    (k.strip() if k else ""): (v.strip() if v else "")
                    for k, v in row.items()
                }
                case_number = cleaned_row.get("CASE_NUMBER")
                if case_number:
                    if case_number not in entity_records:
                        entity_records[case_number] = []
                    entity_records[case_number].append(cleaned_row)

    output = {}

    for pair in manifest.get("pairs", []):
        if "::" in pair:
            rule_id, entity = pair.split("::", 1)
        else:
            rule_id, entity = pair, ""

        facts_list = manifest.get("facts", {}).get(rule_id, [])
        output[pair] = {}

        records = entity_records.get(entity, [])

        for fact_name in facts_list:
            if fact_name not in FACT_CONFIG:
                output[pair][fact_name] = "ABSENT"
                continue

            field_name, formatter, doc_name = FACT_CONFIG[fact_name]
            extracted_values = set()

            for rec in records:
                raw_val = rec.get(field_name, "")
                formatted_val = formatter(raw_val)
                if formatted_val is not None and formatted_val != "":
                    extracted_values.add(formatted_val)

            if len(extracted_values) == 0:
                output[pair][fact_name] = "ABSENT"
            elif len(extracted_values) == 1:
                val = next(iter(extracted_values))
                output[pair][fact_name] = [val, doc_name]
            else:
                output[pair][fact_name] = "CONFLICT"

    print(json.dumps(output, indent=2))

if __name__ == "__main__":
    main()
